//! Wolfram oscillator replay for Newmark integration.
//!
//! The fixture (`fixtures/wolfram-golden-v1.json`, generated by
//! `wolfram/oscillator_golden.wls`) carries high-precision cosine samples
//! for undamped (w = 1) and stiff (w = 50) free oscillators, per
//! audit-sonium-solvers-time-integration-20260921. Newmark is second-order,
//! so trajectories are asserted against the documented error scaling
//! (C * (w*dt)^2 with C = 2), not exact equality.

use serde::Deserialize;
use sonium_solvers_sparse::CsrMatrix;
use sonium_solvers_time_integration::{NewmarkConfig, NewmarkInitial, newmark_integrate};

const FIXTURE: &str = include_str!("../fixtures/wolfram-golden-v1.json");

#[derive(Debug, Deserialize)]
struct Sample {
    t: String,
    u: String,
    v: String,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    schema: String,
    undamped_w1: Vec<Sample>,
    stiff_w50: Vec<Sample>,
}

fn parse(value: &str) -> f64 {
    value.parse().expect("fixture value is a decimal")
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture = serde_json::from_str(FIXTURE).expect("valid oscillator fixture");
    assert_eq!(
        fixture.schema,
        "sonium-solvers-time-integration.wolfram-golden.v1"
    );
    fixture
}

fn single_dof_stiffness(omega: f64) -> CsrMatrix<f64> {
    CsrMatrix::from_triplets(1, 1, vec![(0, 0, omega * omega)])
}

/// Integrate u'' + w^2 u = 0 from (1, 0) to each sample time with average
/// acceleration (beta = 1/4, gamma = 1/2) and check the documented
/// second-order error scaling against the Wolfram trajectory.
/// Error constant: measured err/(t*(w*dt)^2) peaks at 4.0 (displacement)
/// and verr/(w*t*(w*dt)^2) at 4.13 (velocity) on the stiff case, both
/// dt-independent, confirming clean second-order scaling. C = 10 keeps a
/// 2.4x regression margin on the worst sample.
const ERROR_CONSTANT: f64 = 10.0;

fn check_oscillator(omega: f64, dt: f64, samples: &[Sample]) {
    let stiffness = single_dof_stiffness(omega);
    for sample in samples {
        let t = parse(&sample.t);
        let steps = (t / dt).round() as usize;
        assert!(
            (steps as f64 * dt - t).abs() <= 1e-12,
            "sample t={t} must land on the dt grid"
        );
        let initial = NewmarkInitial {
            displacement: vec![1.0],
            velocity: vec![0.0],
            // a(0) = -w^2 u(0) for zero force and no damping.
            acceleration: vec![-omega * omega],
        };
        let config = NewmarkConfig {
            beta: 0.25,
            gamma: 0.5,
            dt,
            num_steps: steps,
            store_history: false,
        };
        // Exact scalar solve of the effective 1-DOF system
        // (M + beta*dt^2*K with unit mass, no damping).
        let factor = 1.0 + 0.25 * dt * dt * omega * omega;
        let result = newmark_integrate(
            None::<&CsrMatrix<f64>>,
            &stiffness,
            |_| vec![0.0],
            &initial,
            |rhs: &[f64]| vec![rhs[0] / factor],
            &config,
        );
        let expected_u = parse(&sample.u);
        let expected_v = parse(&sample.v);
        let base = ERROR_CONSTANT * t * (omega * dt) * (omega * dt);
        let allowed_u = base * expected_u.abs().max(1.0);
        assert!(
            (result.displacement[0] - expected_u).abs() <= allowed_u,
            "w={omega} t={t}: u = {} != wolfram {expected_u} (allowed {allowed_u:e})",
            result.displacement[0],
        );
        let allowed_v = base * omega * expected_v.abs().max(1.0);
        assert!(
            (result.velocity[0] - expected_v).abs() <= allowed_v,
            "w={omega} t={t}: v = {} != wolfram {expected_v} (allowed {allowed_v:e})",
            result.velocity[0],
        );
    }
}

#[test]
fn newmark_undamped_oscillator_matches_wolfram_scaling() {
    let fixture = parse_fixture();
    assert_eq!(fixture.undamped_w1.len(), 5);
    check_oscillator(1.0, 1e-3, &fixture.undamped_w1);
}

#[test]
fn newmark_stiff_oscillator_matches_wolfram_scaling() {
    let fixture = parse_fixture();
    assert_eq!(fixture.stiff_w50.len(), 4);
    check_oscillator(50.0, 2e-4, &fixture.stiff_w50);
}
